import accountApi from 'apis/accountApi';
import { UX } from 'constant';
import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { setMessage } from 'redux/slices/message.slice';
import Login from './index';

function LoginData() {
  const [loading, setLoading] = useState(false);
  const dispatch = useDispatch();

  const handleLogin = async (account) => {
    try {
      setLoading(true);
      const { email, password, loginType } = account;

      const apiRes = await accountApi.postLogin(email.toLowerCase(), password);
      if (apiRes && apiRes.status === 200) {
        // Clear any existing admin status
        localStorage.removeItem('isAdmin');

        // Check for admin email in both regular and Google login
        if (email.toLowerCase() === 'nhathuy1237890@gmail.com' || 
            (loginType === 'google' && apiRes.data?.email?.toLowerCase() === 'nhathuy1237890@gmail.com')) {
          localStorage.setItem('isAdmin', 'true');
        }

        dispatch(
          setMessage({ message: 'Đăng nhập thành công', type: 'success' }),
        );

        setTimeout(() => {
          window.location.reload();
        }, UX.DELAY_TIME);
      }
    } catch (error) {
      const message = error.response?.data?.message || 'Thất bại, thử lại !';
      dispatch(setMessage({ message, type: 'error' }));
      setLoading(false);
    }
  };

  return <Login onLogin={handleLogin} loading={loading} />;
}

export default LoginData;
